package store

type Store interface {
	Get(key string) ([]byte, error)
	Put(key string, val []byte) error
	Delete(key string) error
	Keys() []string
}

type memory struct {
	data map[string][]byte
}

func (m *memory) Get(key string) ([]byte, error) {
	return m.data[key], nil
}

